17	// RateLimiter keeps one token bucket per client IP.
18	type RateLimiter struct {
19		mu       sync.Mutex
20		visitors map[string]*visitor
21		rps      rate.Limit
22		burst    int
23	}
24	
25	func NewRateLimiter(rps float64, burst int) *RateLimiter {
26		return &RateLimiter{visitors: map[string]*visitor{}, rps: rate.Limit(rps), burst: burst}
27	}
28	
29	func (rl *RateLimiter) get(ip string) *rate.Limiter {
30		rl.mu.Lock()
31		defer rl.mu.Unlock()
32		v, ok := rl.visitors[ip]
33		if !ok {
34			v = &visitor{limiter: rate.NewLimiter(rl.rps, rl.burst)}
35			rl.visitors[ip] = v
36		}
37		v.lastSeen = time.Now()
38		return v.limiter
39	}
