41	func clientIP(r *http.Request) string {
42		if xff := r.Header.Get("X-Forwarded-For"); xff != "" {
43			return xff
44		}
45		host, _, err := net.SplitHostPort(r.RemoteAddr)
46		if err != nil {
47			return r.RemoteAddr
48		}
49		return host
50	}
51	
52	func (rl *RateLimiter) Middleware(next http.Handler) http.Handler {
53		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
54			if !rl.get(clientIP(r)).Allow() {
55				http.Error(w, "rate limit exceeded", http.StatusTooManyRequests)
56				return
57			}
58			next.ServeHTTP(w, r)
59		})
60	}

 1	//! Small statistics helpers for the latency report.
 2	
 3	/// Arithmetic mean; `None` for an empty slice.
 4	pub fn mean(xs: &[f64]) -> Option<f64> {
 5	    if xs.is_empty() {
 6	        return None;
 7	    }
 8	    Some(xs.iter().sum::<f64>() / xs.len() as f64)
 9	}
10	
11	/// p-th percentile by nearest rank, `p` in 0..=100.
12	pub fn percentile(sorted: &[f64], p: f64) -> f64 {
13	    let rank = ((p / 100.0) * sorted.len() as f64).ceil() as usize;
14	    sorted[rank.saturating_sub(1).min(sorted.len() - 1)]
15	}
16	
17	/// Median; sorts `xs` in place.
18	pub fn median(xs: &mut [f64]) -> Option<f64> {
19	    if xs.is_empty() {
20	        return None;
21	    }
22	    xs.sort_by(|a, b| a.partial_cmp(b).unwrap());
23	    let mid = xs.len() / 2;
24	    if xs.len() % 2 == 0 {
25	        Some((xs[mid - 1] + xs[mid]) / 2.0)
26	    } else {
27	        Some(xs[mid])
28	    }
29	}

1	export function formatDueDate(due: string, now: Date = new Date()): string {
2	  // due is an ISO date like "2026-10-26"
3	  const today = now.toISOString().slice(0, 10);
4	  if (due === today) return "Today";
5	  const d = new Date(due);
6	  const diffDays = Math.round((d.getTime() - now.getTime()) / 86_400_000);
7	  if (diffDays === 1) return "Tomorrow";
8	  return d.toLocaleDateString("en-US", { month: "short", day: "numeric" });
9	}

