 1	package ring
 2	
 3	// Ring is a fixed-size circular buffer of samples.
 4	type Ring struct {
 5		buf  []float64
 6		head int // index of the oldest sample
 7		n    int // number of slots
 8		size int // samples currently held, at most n
 9	}
10	
11	func New(n int) *Ring {
12		if n <= 0 {
13			panic("ring: size must be positive")
14		}
15		return &Ring{buf: make([]float64, n), n: n}
16	}
17	
18	// Next returns the slot after i, wrapping to 0.
19	func (r *Ring) Next(i int) int { return (i + 1) % r.n }
20	
21	// Prev returns the slot before i, wrapping to n-1.
22	func (r *Ring) Prev(i int) int { return (i - 1 + r.n) % r.n }
23	
24	// Push appends v, overwriting the oldest sample when full.
25	func (r *Ring) Push(v float64) {
26		tail := (r.head + r.size) % r.n
27		r.buf[tail] = v
28		if r.size < r.n {
29			r.size++
30			return
31		}
32		r.head = r.Next(r.head)
33	}
34	
35	// Last returns the newest sample, and false when the ring is empty.
36	func (r *Ring) Last() (float64, bool) {
37		if r.size == 0 {
38			return 0, false
39		}
40		tail := (r.head + r.size) % r.n
41		return r.buf[r.Prev(tail)], true
42	}

 1	package queue
 2	
 3	import "sync"
 4	
 5	type Job func()
 6	
 7	type Queue struct {
 8		jobs    chan Job
 9		wg      sync.WaitGroup
10		closed  bool
11		workers int
12	}
13	
14	func New(workers, buffer int) *Queue {
15		return &Queue{jobs: make(chan Job, buffer), workers: workers}
16	}
17	
18	// Submit enqueues a job; it drops the job if the queue is closed.
19	func (q *Queue) Submit(j Job) {
20		if q.closed {
21			return
22		}
23		q.jobs <- j
24	}
25	
26	// Start launches the workers.
27	func (q *Queue) Start() {
28		for i := 0; i < q.workers; i++ {
29			q.wg.Add(1)
30			go q.worker()
31		}
32	}
33	
34	func (q *Queue) worker() {
35		defer q.wg.Done()
36		for {
37			select {
38			case j := <-q.jobs:
39				j()
40			default:
41				if q.closed {
42					return
43				}
44			}
45		}
46	}
47	
48	// Drain stops accepting jobs and waits for the workers to finish.
49	// Jobs still buffered when Drain is called may be dropped (see #77).
50	func (q *Queue) Drain() {
51		if q.closed {
52			return
53		}
54		// Workers notice the flag the next time
55		// the channel is empty, and return.
56		// Anything already buffered is still run
57		// as long as a worker reaches it first.
58		q.closed = true
59		q.wg.Wait()
60	}
